def verse(s, a): return next(v["text"] for v in Q[str(s)] if v["verse"] == a)
RB = "رَبَّنَا"
H = "[\u064B-\u0652\u0670]*"
RBX = "ر\u0651?\u064e?\u0651?ب(?:\u0651\u064e|\u064e\u0651)ن\u064eا"

def cut(s, a_from, a_to=None, nth=1, stop_next=False, whole=False):
    a_to = a_to or a_from
    t = " ".join(verse(s, a) for a in range(a_from, a_to + 1))
    if whole: return t
    idx = [m.start() for m in re.finditer(RBX, t)]
    st = idx[nth - 1]; en = len(t)
    if stop_next and len(idx) > nth: en = idx[nth]
    return t[st:en].strip(" ۚۖۗۛ")

